template <typename T>
struct QMetaTypeIdQObject<T*, QMetaType::PointerToQObject>
{
    enum {
        Defined = 1
    };

    static int qt_metatype_id()
    {
        // registers under the type's own name, which keeps "const T*"
        // distinct from "T*"
        return QMetaType::fromType<T *>().id();
    }
};

