input.new_string:
    The array only exist of all the types can be registered as a metatype
    (detected using the TypesAreDeclaredMetaType helper struct): either
    they are declared (Q_DECLARE_METATYPE, built-in, Q_GADGET, Q_ENUM,
    pointer to QObject...), or they are complete types that QMetaType can
    handle. Calling types() registers them.
    If one of the type cannot be registered, the function return 0 and the
    types will be computed from the signal's signature when needed.
*/
struct ConnectionTypesCompletenessTag;

template <typename Arg> constexpr bool isConnectionTypeRegistrable()
{
    using T = typename MetatypeDecay<Arg>::type;
    if constexpr (bool(QMetaTypeId2<Arg>::Defined)) {
        return true;
    } else if constexpr (std::is_reference_v<T> || std::is_void_v<T>) {
        return false;
    } else if constexpr (!is_complete<T, ConnectionTypesCompletenessTag>::value) {
        return false;
    } else if constexpr (std::is_pointer_v<T> && !IsPointerDeclaredOpaque<T>::value) {
        using Pointed = std::remove_pointer_t<T>;
        return std::is_void_v<std::remove_cv_t<Pointed>>
                || is_complete<Pointed, ConnectionTypesCompletenessTag>::value;
    } else {
        return true;
    }
}

template <typename Arg> int connectionTypeId()
{
    if constexpr (bool(QMetaTypeId2<Arg>::Defined))
        return QMetaTypeIdHelper<Arg>::qt_metatype_id();
    else
        return QMetaType::fromType<Arg>().id();
}

template <typename ArgList> struct TypesAreDeclaredMetaType { enum { Value = false }; };
template <> struct TypesAreDeclaredMetaType<List<>> { enum { Value = true }; };
template <typename Arg, typename... Tail> struct TypesAreDeclaredMetaType<List<Arg, Tail...> >
{ enum { Value = isConnectionTypeRegistrable<Arg>() && TypesAreDeclaredMetaType<List<Tail...>>::Value }; };

template <typename ArgList, bool Declared = TypesAreDeclaredMetaType<ArgList>::Value > struct ConnectionTypes
{ static const int *types() { return nullptr; } };
template <> struct ConnectionTypes<List<>, true>
{ static const int *types() { return nullptr; } };
template <typename... Args> struct ConnectionTypes<List<Args...>, true>
{ static const int *types() { static const int t[sizeof...(Args) + 1] = { (QtPrivate::connectionTypeId<Args>())..., 0 }; return t; } };

